from taf.ul.sc.uesim.generic_executor import GenericExecutor


class Executor(GenericExecutor):

    basic_state = 'CUS'

    def __init__(self,
                 device_name='CUS',     # type: 'Optional[str]'
                 device=None,           # type: 'Optional[CUS]'
                 autoconnect=False,     # type: 'Optional[bool]'
                 get_device=False       # type: 'Optional[bool]'
                 ):
        super(Executor, self).__init__(device_name=device_name, device=device, autoconnect=autoconnect,
                                       get_device=get_device)

    def align_cus_cell_to_small_cell(self, timeout=120):
        self.align_rtg_cell_to_small_cell(timeout=timeout)

    def align_cus_cell_to_lbr_device(self, timeout=120):
        self.align_rtg_cell_to_lbr_device(timeout=timeout)

    def align_cus_cell_to_radio_cell(self, target='', timeout=120):
        self.align_rtg_cell_to_radio_cell(target=target, timeout=timeout)

    def start_cus_scenario(self, scenario_name="attach", timeout=300):
        return self.start_rtg_scenario(scenario_name=scenario_name, timeout=timeout)

    def stop_cus_scenario(self, timeout=180):
        self.stop_rtg_scenario(timeout=timeout)
